using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpApiServer;

/// <summary>
/// Tools are discovered by the MCP SDK via [McpServerToolType] on the class
/// and [McpServerTool] on each method. Constructor parameters (here HttpClient)
/// are resolved from the DI container — the SDK instantiates this class per
/// tool invocation using ActivatorUtilities, so standard constructor injection
/// works out of the box.
/// </summary>
[McpServerToolType]
public class WeatherTools(HttpClient httpClient)
{
    private const string BaseUrl = "https://api.open-meteo.com/v1";

    [McpServerTool, Description("Get current weather for a latitude/longitude coordinate.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude (-90 to 90)")] double latitude,
        [Description("Longitude (-180 to 180)")] double longitude,
        CancellationToken cancellationToken = default)
    {
        var url = $"{BaseUrl}/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m,relative_humidity_2m";

        var response = await httpClient.GetFromJsonAsync<WeatherResponse>(url, cancellationToken)
            ?? throw new InvalidOperationException("Empty response from weather API.");

        var c = response.Current;
        return $"Temperature: {c.Temperature}°C, Wind: {c.WindSpeed} km/h, Humidity: {c.Humidity}%";
    }

    [McpServerTool, Description("Get a multi-day weather forecast for a location.")]
    public async Task<string> GetForecast(
        [Description("Latitude (-90 to 90)")] double latitude,
        [Description("Longitude (-180 to 180)")] double longitude,
        [Description("Number of forecast days (1-16)")] int days = 7,
        CancellationToken cancellationToken = default)
    {
        days = Math.Clamp(days, 1, 16);
        var url = $"{BaseUrl}/forecast?latitude={latitude}&longitude={longitude}"
                + $"&daily=temperature_2m_max,temperature_2m_min&forecast_days={days}";

        var response = await httpClient.GetFromJsonAsync<ForecastResponse>(url, cancellationToken)
            ?? throw new InvalidOperationException("Empty response from weather API.");

        var lines = response.Daily.Time
            .Select((date, i) =>
                $"{date}: {response.Daily.MinTemp[i]}°C – {response.Daily.MaxTemp[i]}°C")
            .ToList();

        return string.Join('\n', lines);
    }
}

// --- DTOs -----------------------------------------------------------------

